SET standard_conforming_strings = OFF;
DROP TABLE IF EXISTS "public"."cities" CASCADE;
BEGIN;
CREATE TABLE "public"."cities" ( "ogc_fid" SERIAL, CONSTRAINT "cities_pk" PRIMARY KEY ("ogc_fid") );
SELECT AddGeometryColumn('public','cities','wkb_geometry',4326,'MULTIPOLYGON',2);
CREATE INDEX "cities_wkb_geometry_geom_idx" ON "public"."cities" USING GIST ("wkb_geometry");
ALTER TABLE "public"."cities" ADD COLUMN "city_name" VARCHAR(25);
ALTER TABLE "public"."cities" ADD COLUMN "city_eng" VARCHAR(50);
ALTER TABLE "public"."cities" ADD COLUMN "ostan_name" VARCHAR(50);
COMMIT;
